CREATE TABLE IF NOT EXISTS public.cash_registers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE, opened_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, opening_amount numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'open', opened_at timestamptz NOT NULL DEFAULT now(), closed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, closed_at timestamptz, counted_cash numeric, CONSTRAINT cash_registers_opening_amount_check CHECK(opening_amount>=0), CONSTRAINT cash_registers_counted_cash_check CHECK(counted_cash IS NULL OR counted_cash>=0), CONSTRAINT cash_registers_status_check CHECK(status IN ('open','closed')));
CREATE UNIQUE INDEX IF NOT EXISTS uq_cash_register_open_business ON public.cash_registers(business_id) WHERE status='open';
CREATE INDEX IF NOT EXISTS idx_cash_registers_business_opened ON public.cash_registers(business_id,opened_at DESC);
CREATE TABLE IF NOT EXISTS public.cash_register_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE, cash_register_id uuid NOT NULL REFERENCES public.cash_registers(id) ON DELETE CASCADE, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, movement_type text NOT NULL, amount numeric NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT cash_register_movements_type_check CHECK(movement_type IN ('deposit','withdrawal')), CONSTRAINT cash_register_movements_amount_check CHECK(amount>0));
CREATE INDEX IF NOT EXISTS idx_cash_register_movements_register_date ON public.cash_register_movements(cash_register_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_cash_register_movements_business_date ON public.cash_register_movements(business_id,created_at DESC);
ALTER TABLE public.cash_registers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cash_register_movements ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS cash_registers_select_member ON public.cash_registers;
DROP POLICY IF EXISTS cash_registers_insert_staff ON public.cash_registers;
DROP POLICY IF EXISTS cash_registers_update_staff ON public.cash_registers;
DROP POLICY IF EXISTS cash_register_movements_select_member ON public.cash_register_movements;
DROP POLICY IF EXISTS cash_register_movements_insert_staff ON public.cash_register_movements;
CREATE POLICY cash_registers_select_member ON public.cash_registers FOR SELECT TO authenticated USING(private.is_business_member(business_id,(select auth.uid())));
CREATE POLICY cash_registers_insert_staff ON public.cash_registers FOR INSERT TO authenticated WITH CHECK(private.has_business_role(business_id,(select auth.uid()),ARRAY['owner'::member_role,'admin'::member_role,'staff'::member_role]));
CREATE POLICY cash_registers_update_staff ON public.cash_registers FOR UPDATE TO authenticated USING(private.has_business_role(business_id,(select auth.uid()),ARRAY['owner'::member_role,'admin'::member_role,'staff'::member_role])) WITH CHECK(private.has_business_role(business_id,(select auth.uid()),ARRAY['owner'::member_role,'admin'::member_role,'staff'::member_role]));
CREATE POLICY cash_register_movements_select_member ON public.cash_register_movements FOR SELECT TO authenticated USING(private.is_business_member(business_id,(select auth.uid())));
CREATE POLICY cash_register_movements_insert_staff ON public.cash_register_movements FOR INSERT TO authenticated WITH CHECK(private.has_business_role(business_id,(select auth.uid()),ARRAY['owner'::member_role,'admin'::member_role,'staff'::member_role]));
CREATE OR REPLACE FUNCTION private.sync_cash_register_movement_ledger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ BEGIN IF TG_OP='DELETE' THEN DELETE FROM public.financial_cash_ledger WHERE business_id=OLD.business_id AND source_type='cash_register_movement' AND source_id=OLD.id; RETURN OLD; END IF; DELETE FROM public.financial_cash_ledger WHERE business_id=NEW.business_id AND source_type='cash_register_movement' AND source_id=NEW.id; INSERT INTO public.financial_cash_ledger(business_id,entry_date,direction,amount,category,description,payment_method,source_type,source_id) VALUES(NEW.business_id,NEW.created_at::date,CASE WHEN NEW.movement_type='deposit' THEN 'inflow' ELSE 'outflow' END,NEW.amount,'Caja','Caja: '||NEW.reason,'efectivo','cash_register_movement',NEW.id) ON CONFLICT(business_id,source_type,source_id) DO UPDATE SET entry_date=excluded.entry_date,direction=excluded.direction,amount=excluded.amount,description=excluded.description,updated_at=now(); RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trg_sync_cash_register_movement_ledger ON public.cash_register_movements;
CREATE TRIGGER trg_sync_cash_register_movement_ledger AFTER INSERT OR UPDATE OR DELETE ON public.cash_register_movements FOR EACH ROW EXECUTE FUNCTION private.sync_cash_register_movement_ledger();
REVOKE ALL ON FUNCTION private.sync_cash_register_movement_ledger() FROM PUBLIC,anon,authenticated;
